// Parsear payload de Pine Script
const b = $input.first().json.body || $input.first().json;

const precio_actual    = parseFloat(b.precio_actual) || 0;
const atr              = parseFloat(b.atr) || 1;
const supply_zone_top  = b.supply_zone_top !== 'null' ? parseFloat(b.supply_zone_top) : null;
const supply_zone_bot  = b.supply_zone_bot !== 'null' ? parseFloat(b.supply_zone_bot) : null;
const demand_zone_top  = b.demand_zone_top !== 'null' ? parseFloat(b.demand_zone_top) : null;
const demand_zone_bot  = b.demand_zone_bot !== 'null' ? parseFloat(b.demand_zone_bot) : null;
const nivel_h          = b.nivel_h !== 'null' ? parseFloat(b.nivel_h) : null;
const nivel_l          = b.nivel_l !== 'null' ? parseFloat(b.nivel_l) : null;

// Detectar zona activa (la más cercana al precio)
let zona_activa = null;
let zona_tipo = null;
let dist_supply = Infinity, dist_demand = Infinity;

if (supply_zone_top !== null) {
  const mid_s = (supply_zone_top + supply_zone_bot) / 2;
  dist_supply = Math.abs(precio_actual - mid_s) / precio_actual * 100;
}
if (demand_zone_top !== null) {
  const mid_d = (demand_zone_top + demand_zone_bot) / 2;
  dist_demand = Math.abs(precio_actual - mid_d) / precio_actual * 100;
}

if (supply_zone_top !== null && dist_supply <= dist_demand) {
  zona_activa = { top: supply_zone_top, bot: supply_zone_bot };
  zona_tipo = 'supply';
} else if (demand_zone_top !== null) {
  zona_activa = { top: demand_zone_top, bot: demand_zone_bot };
  zona_tipo = 'demand';
}

// Calcular fase
let fase = 'LEJOS';
if (zona_activa) {
  const dist_pct = zona_tipo === 'supply'
    ? Math.abs(precio_actual - zona_activa.bot) / precio_actual * 100
    : Math.abs(precio_actual - zona_activa.top) / precio_actual * 100;
  if (precio_actual <= zona_activa.top && precio_actual >= zona_activa.bot) {
    fase = 'EN_ZONA';
  } else if (dist_pct < 0.3) {
    fase = 'ACERCANDO';
  }
}

return [{ json: {
  precio_actual, atr,
  supply_zone_top, supply_zone_bot,
  demand_zone_top, demand_zone_bot,
  nivel_h, nivel_l,
  zona_tipo, zona_activa,
  fase
}}];

const datos   = $('Parsear y Detectar Zona').first().json;
const hSupply = $('Historial Supply').all().map(i => i.json);
const hDemand = $('Historial Demand').all().map(i => i.json);
const hNivel  = $('Historial Niveles').all().map(i => i.json);

function calcProbs(arr) {
  const t = arr.length;
  if (t === 0) return { resp_f: 0, resp_d: 0, rompio: 0, casos: 0, suficiente: false };
  const rf = arr.filter(r => r.resultado === 'respeto_fuerte').length;
  const rd = arr.filter(r => r.resultado === 'respeto_debil').length;
  const ro = arr.filter(r => r.resultado === 'rompio').length;
  return {
    resp_f: parseFloat((rf / t * 100).toFixed(2)),
    resp_d: parseFloat((rd / t * 100).toFixed(2)),
    rompio: parseFloat((ro / t * 100).toFixed(2)),
    casos: t,
    suficiente: t >= 15
  };
}

function calcNivel(tipo) {
  const arr = hNivel.filter(n => n.tipo_nivel === tipo);
  const rotos = arr.filter(n => n.fue_roto).length;
  return {
    pct: arr.length > 0 ? parseFloat((rotos / arr.length * 100).toFixed(2)) : 0,
    casos: arr.length
  };
}

const sz = calcProbs(hSupply);
const dz = calcProbs(hDemand);
const nh = calcNivel('H');
const nl = calcNivel('L');

// Score confluencia: zonas 50%, niveles 50%
const zona_score = datos.zona_tipo === 'supply' ? sz.resp_f : dz.resp_f;
const nivel_score = datos.nivel_h ? (100 - nh.pct) : (nl.pct ? nl.pct : 0);
const score = Math.round(zona_score * 0.60 + nivel_score * 0.40);

const zona_activa = datos.zona_activa || {};

return [{ json: {
  id: 1,
  activo: 'XAUUSD',
  tipo_zona: datos.zona_tipo || 'supply',
  precio_zona_suelo: zona_activa.bot || datos.supply_zone_bot || 0,
  precio_zona_techo: zona_activa.top || datos.supply_zone_top || 0,
  direccion_precio: datos.zona_tipo === 'supply' ? 'bajista' : 'alcista',
  prob_respeto_fuerte: datos.zona_tipo === 'supply' ? sz.resp_f : dz.resp_f,
  prob_respeto_debil:  datos.zona_tipo === 'supply' ? sz.resp_d : dz.resp_d,
  prob_rompio:         datos.zona_tipo === 'supply' ? sz.rompio : dz.rompio,
  casos_totales:       datos.zona_tipo === 'supply' ? sz.casos  : dz.casos,
  muestra_suficiente:  datos.zona_tipo === 'supply' ? sz.suficiente : dz.suficiente,
  // supply stats
  sz_resp_f: sz.resp_f, sz_resp_d: sz.resp_d, sz_rompio: sz.rompio, sz_casos: sz.casos,
  // demand stats
  dz_resp_f: dz.resp_f, dz_resp_d: dz.resp_d, dz_rompio: dz.rompio, dz_casos: dz.casos,
  // niveles
  nivel_arriba_tipo: 'H',
  nivel_arriba_precio: datos.nivel_h,
  nivel_arriba_prob_ruptura: nh.pct,
  nivel_arriba_casos: nh.casos,
  nivel_abajo_tipo: 'L',
  nivel_abajo_precio: datos.nivel_l,
  nivel_abajo_prob_soporte: 100 - nl.pct,
  nivel_abajo_casos: nl.casos,
  score_confluencia: score,
  fase: datos.fase,
  updated_at: new Date().toISOString()
}}];
